// Support both storage keys for backward compatibility
const STORAGE_KEYS = ['scos_language', 'cafeteria_language', 'language'];

// === Centralized translation files (en.json / am.json) ===
// Single source of truth per requirement: en.json & am.json
const CENTRAL_LOCALE_PATHS = {
  en: [
    '/src/locales/en.json',
    '/locales/en.json',
    '/public/locales/en.json',
    '../locales/en.json',
    '../../locales/en.json',
    './src/locales/en.json',
  ],
  am: [
    '/src/locales/am.json',
    '/locales/am.json',
    '/public/locales/am.json',
    '../locales/am.json',
    '../../locales/am.json',
    './src/locales/am.json',
  ],
};

let centralLoaded = false;

// Registry of callbacks invoked whenever the active language changes. Admin and
// kitchen components register here so they can re-render dynamic content (table
// rows, badges, chart labels, loading messages) in the newly selected language.
const languageRenderCallbacks = new Set();

export function onLanguageChange(callback) {
  if (typeof callback === 'function') languageRenderCallbacks.add(callback);
  return () => languageRenderCallbacks.delete(callback);
}

/**
 * Timing-safe language re-render registration. Classic scripts that run while
 * i18n.js (type=module) has not executed yet still get a working subscription
 * via the language:changed / languageChanged events that setLanguage dispatches.
 * Prefer this over a bare `typeof window.onLanguageChange === 'function'` check.
 */
export function onLanguageChangeSafe(callback) {
  if (typeof callback !== 'function') return () => {};
  if (typeof window.onLanguageChange === 'function' && window.onLanguageChange === onLanguageChange) {
    return window.onLanguageChange(callback);
  }
  // i18n not ready yet (or replaced) — fall back to event listeners so the
  // callback still fires on every language switch without a page refresh.
  const handler = (e) => callback(e && e.detail && e.detail.language);
  window.addEventListener('language:changed', handler);
  window.addEventListener('languageChanged', handler);
  return () => {
    window.removeEventListener('language:changed', handler);
    window.removeEventListener('languageChanged', handler);
  };
}

export function triggerLanguageRender() {
  languageRenderCallbacks.forEach(function (cb) {
    try {
      cb(getCurrentLanguage());
    } catch (_) {}
  });
}

// Backwards-compatible global registration helpers
window.onLanguageChange = onLanguageChange;
window.onLanguageChangeSafe = onLanguageChangeSafe;
window.i18nOnLanguageChange = onLanguageChange;
window.triggerLanguageRender = triggerLanguageRender;
window.i18nTriggerLanguageRender = triggerLanguageRender;

async function fetchJsonWithFallback(paths) {
  for (const p of paths) {
    try {
      const res = await fetch(p, { cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        if (data && typeof data === 'object' && Object.keys(data).length > 0) return data;
      }
    } catch (_) {}
  }
  return null;
}

async function loadCentralizedTranslations() {
  if (centralLoaded) return;
  try {
    const [enData, amData] = await Promise.all([
      fetchJsonWithFallback(CENTRAL_LOCALE_PATHS.en),
      fetchJsonWithFallback(CENTRAL_LOCALE_PATHS.am),
    ]);
    let updated = false;
    if (enData) {
      Object.assign(translations.en, enData);
      updated = true;
    }
    if (amData) {
      Object.assign(translations.am, amData);
      updated = true;
    }
    if (updated) {
      centralLoaded = true;
      applyTranslations();
    }
  } catch (_) {}
  centralLoaded = true;
}

function readLanguage() {
  for (const k of STORAGE_KEYS) {
    const v = localStorage.getItem(k);
    if (v === 'en' || v === 'am') return v;
  }
  return 'en';
}

function writeLanguage(lang) {
  const normalized = lang === 'am' ? 'am' : 'en';
  for (const k of STORAGE_KEYS) {
    localStorage.setItem(k, normalized);
  }
  // Also sync profile language preference if exists
  try {
    const profileRaw = localStorage.getItem('userProfile');
    if (profileRaw) {
      const p = JSON.parse(profileRaw);
      if (p && typeof p === 'object') {
        p.language = normalized;
        localStorage.setItem('userProfile', JSON.stringify(p));
      }
    }
  } catch (_) {}
}

export function getCurrentLanguage() {
  return readLanguage();
}

export function setLanguage(lang) {
  if (lang !== 'en' && lang !== 'am') return;
  writeLanguage(lang);
  applyTranslations();
  triggerLanguageRender();
  // Persist immediately without refresh - update selectors & dispatch events
  document.querySelectorAll('.scos-lang-select, #langToggleSelect, #preferred-language').forEach((s) => {
    s.value = lang;
  });
  window.dispatchEvent(new CustomEvent('language:changed', { detail: { language: lang } }));
  window.dispatchEvent(new CustomEvent('languageChanged', { detail: { language: lang } }));
  // Ensure body class reflects immediately
  try {
    document.documentElement.lang = lang;
    document.body.classList.toggle('lang-am', lang === 'am');
    document.body.classList.toggle('lang-en', lang === 'en');
  } catch (_) {}
}

export function getText(key) {
  const lang = getCurrentLanguage();
  return translations[lang]?.[key] || translations.en[key] || key;
}

/**
 * Key-based UI helper. Always prefers the active language, then English
 * fallback text. Supports simple {placeholder} variable substitution.
 * Use this for all dynamic JS strings instead of bilingual ternaries.
 */
export function tr(key, fallback, vars) {
  let val = translations[getCurrentLanguage()]?.[key] || translations.en[key];
  if (val === undefined || val === null || val === '') {
    val = fallback !== undefined && fallback !== null && fallback !== '' ? fallback : key;
  }
  if (vars && typeof vars === 'object') {
    Object.keys(vars).forEach((k) => {
      val = String(val).split('{' + k + '}').join(String(vars[k]));
    });
  }
  return val;
}

// Backend returns English messages (and sometimes error codes). Map them to
// stable i18n keys once, at the API edge, so pages never re-translate raw
// server text page-by-page.
const ERROR_MESSAGE_PATTERNS = [
  { re: /session expired/i, key: 'error_session_expired' },
  // Auth failures must be classified BEFORE the generic "required"/"invalid
  // value" rule below, or the backend's "Authentication required" and "Invalid
  // or expired token" get shown as "Please check the form and try again."
  { re: /authentication required|not authorized|unauthorized|not authenticated|please log in|login required|invalid or expired token|expired token|token (?:has )?expired|jwt (?:expired|invalid|malformed)/i, key: 'error_unauthorized' },
  { re: /access denied|insufficient permission|forbidden/i, key: 'error_forbidden' },
  { re: /not found/i, key: 'error_not_found' },
  { re: /order not found/i, key: 'error_order_not_found' },
  { re: /payment (failed|error)|failed to (initiate|process) payment/i, key: 'error_payment_failed' },
  { re: /invalid (email|password|credentials)|wrong password/i, key: 'error_invalid_credentials' },
  { re: /already (exists|registered)/i, key: 'error_email_exists' },
  { re: /required|must be|invalid (value|input|format)|validation/i, key: 'error_validation' },
  { re: /too many requests|rate limit/i, key: 'error_too_many_requests' },
  { re: /timed? ?out/i, key: 'error_timeout' },
  { re: /failed to fetch|could not connect|network/i, key: 'error_network' },
  { re: /server error|internal server|try again later/i, key: 'error_server' },
  { re: /invalid server response/i, key: 'error_invalid_response' },
  { re: /out of stock|unavailable|not available/i, key: 'error_stock_unavailable' },
];

function normalizeErrorCode(raw) {
  return String(raw || '')
    .trim()
    .toUpperCase()
    .replace(/^ERROR_/, '')
    .replace(/[^A-Z0-9]+/g, '_')
    .replace(/^_|_$/g, '');
}

/**
 * Translate a backend error message or error CODE into the active language.
 * Priority: explicit error code key → pattern-matched key → original text.
 * Never invents per-page strings: codes map through status_* / error_* keys only.
 */
export function translateErrorMessage(message, code) {
  const lang = getCurrentLanguage();
  const t = translations[lang] || translations.en;
  const codeNorm = normalizeErrorCode(code);
  if (codeNorm) {
    const codeKey = 'error_' + codeNorm;
    if (t[codeKey] || translations.en[codeKey]) return getText(codeKey);
    if (t[codeNorm] || translations.en[codeNorm]) return getText(codeNorm);
    if (STATUS_CODE_TO_KEY[codeNorm]) return getText(STATUS_CODE_TO_KEY[codeNorm]);
  }
  if (message === undefined || message === null || message === '') {
    return getText('error_unknown');
  }
  const msgStr = String(message);
  // Already a translation key?
  if (t[msgStr] || translations.en[msgStr]) return getText(msgStr);
  const msgCode = normalizeErrorCode(msgStr);
  if (msgCode && msgCode !== msgStr.toUpperCase()) {
    const codeKey = 'error_' + msgCode;
    if (t[codeKey] || translations.en[codeKey]) return getText(codeKey);
  }
  for (const p of ERROR_MESSAGE_PATTERNS) {
    if (p.re.test(msgStr)) return getText(p.key);
  }
  // Leave unknown backend text as-is (user-provided names, addresses, etc.)
  return msgStr;
}

// Map raw API/database status codes (which must never be translated at the
// data layer) to the display-only, localized label shown to users.
const STATUS_CODE_TO_KEY = {
  PENDING: 'status_pending',
  PAID: 'status_paid',
  IN_PREP: 'status_preparing',
  'IN-PREP': 'status_preparing',
  INPREP: 'status_preparing',
  PREPARING: 'status_preparing',
  PREPARATION: 'status_preparing',
  READY: 'status_ready',
  SERVED: 'status_served',
  ARRIVED: 'status_arrived',
  COMPLETED: 'status_completed',
  CANCELLED: 'status_cancelled',
  CANCELED: 'status_cancelled',
  FAILED: 'status_failed',
  DELIVERED: 'status_delivered',
  REFUNDED: 'status_refunded',
  PICKED_UP: 'status_picked_up',
  PICKEDUP: 'status_picked_up',
  OUT_FOR_DELIVERY: 'status_out_for_delivery',
  OUTFORDELIVERY: 'status_out_for_delivery',
  ASSIGNED: 'status_assigned',
  ACCEPTED: 'status_accepted',
  DECLINED: 'status_declined',
  PENDING_ACCEPTANCE: 'status_pending_acceptance',
  AWAITING_ACCEPTANCE: 'status_pending_acceptance',
  UNPAID: 'status_unpaid',
  CONFIRMED: 'status_confirmed',
  IN_PREPARATION: 'status_in_preparation',
  OPEN: 'status_open',
  CLOSED: 'status_closed',
  REJECTED: 'status_rejected',
  RESOLVED: 'status_resolved',
  IN_PROGRESS: 'status_in_progress',
  AVAILABLE: 'status_available',
  OCCUPIED: 'status_occupied',
  RESERVED: 'status_reserved',
  MAINTENANCE: 'status_maintenance',
  LOW_STOCK: 'status_low_stock',
  OUT_OF_STOCK: 'status_out_of_stock',
  IN_STOCK: 'status_in_stock',
};

const USER_STATUS_TO_KEY = {
  ACTIVE: 'status_active',
  BLOCKED: 'status_blocked',
  SUSPENDED: 'status_suspended',
  INACTIVE: 'status_inactive',
};

// Display-only translation of a raw status code (order, payment, user...).
export function translateStatus(raw) {
  if (raw === undefined || raw === null || raw === '') return '';
  const norm = String(raw).toUpperCase().replace(/\s+/g, '_').trim();
  const key = STATUS_CODE_TO_KEY[norm] || USER_STATUS_TO_KEY[norm];
  return key ? getText(key) : String(raw);
}

function updateIdTranslations(lang) {
  const t = translations[lang] || translations.en;
  const ids = Object.keys(t);
  ids.forEach((id) => {
    const el = document.getElementById(id);
    if (el) {
      // Skip form controls: setting textContent on a <select> replaces all of
      // its <option> children (e.g. a translation key "severity" must not wipe
      // the #severity select). Text is displayed via value/options/placeholder.
      const tag = el.tagName;
      if (tag === 'SELECT' || tag === 'OPTION' || tag === 'INPUT' || tag === 'TEXTAREA') return;
      const val = t[id];
      if (typeof val === 'string' && val.startsWith('<')) {
        el.innerHTML = val;
      } else if (val) {
        // Preserve icons inside element
        const icon = el.querySelector('i');
        if (icon && el.childNodes.length > 1) {
          const last = el.childNodes[el.childNodes.length - 1];
          if (last && last.nodeType === 3) {
            last.nodeValue = ' ' + val;
          } else {
            el.textContent = val;
            if (icon) el.prepend(icon);
          }
        } else if (icon) {
          const iconHtml = icon.outerHTML;
          el.innerHTML = `${iconHtml} ${val}`;
        } else {
          el.textContent = val;
        }
      }
    }
  });
}

let _applyingTranslations = false;
export function applyTranslations() {
  if (_applyingTranslations) return;
  _applyingTranslations = true;
  const lang = getCurrentLanguage();
  const t = translations[lang] || translations.en;

  // Set html lang & body class
  try {
    document.documentElement.lang = lang;
    document.body.classList.toggle('lang-am', lang === 'am');
    document.body.classList.toggle('lang-en', lang === 'en');
  } catch (_) {}

  // 1. Attribute translation via data-i18n
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    const key = el.getAttribute('data-i18n');
    if (!key) return;
    const val = t[key];
    if (!val) return;
    if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
      if (el.hasAttribute('placeholder')) {
        el.setAttribute('placeholder', val);
      } else {
        el.textContent = val;
      }
    } else if (el.hasAttribute('data-i18n-html')) {
      el.innerHTML = val;
    } else {
      if (el.classList.contains('loading') || (el.tagName === 'BUTTON' && el.disabled)) return;
      const icon = el.querySelector('i');
      if (icon) {
        const iconHtml = icon.outerHTML;
        if (el.textContent.trim() !== val) el.innerHTML = `${iconHtml} ${val}`;
      } else {
        el.textContent = val;
      }
    }
  });

  // Handle placeholder specific attribute
  document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
    const key = el.getAttribute('data-i18n-placeholder');
    const val = key && t[key];
    if (val) el.setAttribute('placeholder', val);
  });

  document.querySelectorAll('[data-i18n-title]').forEach((el) => {
    const key = el.getAttribute('data-i18n-title');
    const val = key && t[key];
    if (val) el.setAttribute('title', val);
  });

  // 2. ID-based translation (for index.html and other pages with IDs matching keys)
  updateIdTranslations(lang);

  // 3. Direct DOM Text mapping fallback (covers hard-coded English without data-i18n)
  const normalize = (s) => String(s).replace(/\s+/g, ' ').trim();

  // Lookup tables, built ONCE per pass instead of once per element.
  //
  // These two loops below run over every link/button/heading/cell/span on the
  // page, and each of them used to walk the whole of directTextMap and
  // re-normalise every entry for every element. On a data-heavy screen (an
  // orders or cashier table with hundreds of rows) that is hundreds of
  // thousands of throwaway arrays and regex passes, which is what pushed the
  // surrounding setTimeout callback past the long-task threshold and produced
  // the "[Violation] 'setTimeout' handler took Nms" warning.
  //
  // Semantics are unchanged: first entry in directTextMap order still wins, so
  // an existing key is never overwritten while building the map.
  const buildLookup = (getTexts) => {
    const lookup = new Map();
    for (const val of Object.values(directTextMap)) {
      for (const raw of getTexts(val)) {
        if (raw === null || raw === undefined) continue;
        const norm = normalize(raw);
        if (norm && !lookup.has(norm)) lookup.set(norm, val);
      }
    }
    return lookup;
  };
  const textLookup = buildLookup((val) => [val.en, val.am]);

  const targets = document.querySelectorAll(
    'a, button, label, h1, h2, h3, h4, h5, th, td, span, p, small, strong, option'
  );
  targets.forEach((el) => {
    // Skip only when data-i18n key actually resolved, or id-based key exists.
    // A missing data-i18n key must NOT block the directTextMap fallback —
    // otherwise that element stays permanently English.
    const di18nKey = el.getAttribute('data-i18n');
    const di18nResolved = !!di18nKey && !!(t[di18nKey] || translations.en[di18nKey]);
    if (di18nResolved || (el.id && (t[el.id] || translations.en[el.id]))) return;
    // Only handle leaf nodes or single-icon wrappers
    const hasOnlyTextOrIcon = el.children.length === 0 || (el.children.length === 1 && el.querySelector('i, svg'));
    if (!hasOnlyTextOrIcon) return;
    // Ignore option elements inside language selectors to avoid infinite loop (we handle separately)
    if (
      el.tagName === 'OPTION' &&
      el.closest('select.scos-lang-select, select#langToggleSelect, select#preferred-language')
    )
      return;
    const lastNode = el.childNodes[el.childNodes.length - 1];
    const rawText = lastNode?.nodeValue?.trim();
    if (!rawText) return;
    const match = textLookup.get(normalize(rawText));
    if (match) {
      const newText = match[lang] || match.en;
      if (el.children.length === 1 && el.querySelector('i, svg')) {
        lastNode.nodeValue = ' ' + newText;
      } else {
        el.textContent = newText;
      }
    }
  });

  // 3b. Placeholder translation (search inputs etc.)
  const placeholderLookup = buildLookup((val) => [val.en, val.am]);
  document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach((el) => {
    if (el.hasAttribute('data-i18n-placeholder') || el.hasAttribute('data-i18n')) return;
    const ph = el.getAttribute('placeholder')?.trim();
    if (!ph) return;
    const match = placeholderLookup.get(normalize(ph));
    if (match) el.setAttribute('placeholder', match[lang] || match.en);
  });

  // 4. Update all dropdown selectors on the page
  document
    .querySelectorAll('.scos-lang-select, #langToggleSelect, #preferred-language, #language-switcher select')
    .forEach((select) => {
      // Only sync language selectors, not other selects
      if (
        select.id === 'preferred-language' ||
        select.classList.contains('scos-lang-select') ||
        select.id === 'langToggleSelect'
      ) {
        select.value = lang;
      }
    });

  // 5. Update dynamic content like menu item names if they have data-lang alternate?
  document.querySelectorAll('[data-en][data-am]').forEach((el) => {
    const val = el.getAttribute(`data-${lang}`);
    if (val) el.textContent = val;
  });
  _applyingTranslations = false;
}

export function renderLangSwitcher(containerElement) {
  if (!containerElement) return;
  const currentLang = getCurrentLanguage();
  // Complete English / Amharic switcher per requirement - immediate switch without refresh
  containerElement.innerHTML = `
    <div class="lang-switcher-widget" style="display:inline-flex;align-items:center;gap:6px;margin:0 8px;background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;padding:3px 8px;box-shadow:0 2px 8px rgba(0,0,0,0.08);">
      <i class="fa-solid fa-globe" style="color:#2563eb;font-size:13px;"></i>
      <select class="scos-lang-select" aria-label="Language Selector" style="background:transparent;color:#0f172a;border:none;font-weight:700;cursor:pointer;font-size:13px;outline:none;min-width:110px;">
        <option value="en" ${currentLang === 'en' ? 'selected' : ''}>🇬🇧 English</option>
        <option value="am" ${currentLang === 'am' ? 'selected' : ''}>🇪🇹 አማርኛ</option>
      </select>
    </div>
  `;
  const selectEl = containerElement.querySelector('.scos-lang-select');
  if (selectEl) {
    selectEl.value = currentLang;
    selectEl.addEventListener('change', (e) => setLanguage(e.target.value));
  }
}

function ensureSwitcherInjected() {
  if (document.querySelector('.scos-lang-select, #langToggleSelect')) {
    // Sync value but still ensure admin/kitchen headers have it if missing there
    const existsInAdminNav = document.querySelector('.admin-navbar .scos-lang-select');
    const existsInKds = document.querySelector('.kds-header .scos-lang-select');
    if (!existsInAdminNav && document.querySelector('.admin-navbar .nav-right')) {
      const wrapper = document.createElement('span');
      wrapper.style.display = 'inline-flex';
      wrapper.style.alignItems = 'center';
      wrapper.style.marginRight = '12px';
      renderLangSwitcher(wrapper);
      const navRight = document.querySelector('.admin-navbar .nav-right');
      navRight.prepend(wrapper);
    }
    if (!existsInKds && document.querySelector('.kds-header')) {
      const wrapper = document.createElement('span');
      renderLangSwitcher(wrapper);
      const kdsHeader = document.querySelector('.kds-header');
      const actions = kdsHeader.querySelector('.user-menu');
      if (actions) actions.prepend(wrapper);
      else kdsHeader.appendChild(wrapper);
    }
    // A real in-navbar/in-header switcher now exists (e.g. rendered by a shared
    // layout component). Remove any stale floating fallback selector so we never
    // end up with TWO language dropdowns on the same page.
    //
    // IMPORTANT: only remove the floating selector when a real header/host is
    // present. On pages with no header at all the floating selector is the ONLY
    // one, so it must be kept — otherwise the MutationObserver would re-run this
    // function, remove the floating selector, re-inject it, and loop forever.
    const hasRealHost = document.querySelector(
      '.admin-navbar, .kds-header, .nav-container, .header-actions, .nav-right, .navbar-header, .kds-navbar, .cancel-header, header, nav, .header'
    );
    if (hasRealHost) removeStaleFloatingSwitcher();
    return;
  }

  // Try multiple header containers
  const candidates = [
    document.querySelector('.nav-container'),
    document.querySelector('.navbar-header .header-actions'),
    document.querySelector('.header-actions'),
    document.querySelector('.navbar .nav-container'),
    document.querySelector('.nav-right'),
    document.querySelector('.admin-navbar .nav-right'),
    document.querySelector('.kds-header'),
    document.querySelector('header .container'),
    document.querySelector('.header .container'),
    document.querySelector('.header'),
    document.querySelector('.cancel-header'),
    document.querySelector('.kds-navbar'),
    document.querySelector('.navbar-header'),
    document.querySelector('.user-profile-menu'),
    document.querySelector('.nav-auth'),
    document.querySelector('.nav-links'),
    document.querySelector('nav'),
    document.querySelector('header'),
  ].filter(Boolean);

  for (const container of candidates) {
    if (container.querySelector('.scos-lang-select, #langToggleSelect')) continue;
    // Prefer injecting into header actions or nav containers
    const cls = container.className || '';
    const isHost =
      container.classList.contains('nav-container') ||
      container.classList.contains('header-actions') ||
      container.classList.contains('nav-right') ||
      container.classList.contains('kds-header') ||
      container.classList.contains('cancel-header') ||
      container.classList.contains('kds-navbar') ||
      container.classList.contains('header') ||
      (container.tagName === 'HEADER' && !cls.includes('page-')) ||
      container.classList.contains('navbar-header');
    if (!isHost && !(container.tagName === 'NAV')) continue;

    const wrapper = document.createElement('span');
    wrapper.style.display = 'inline-flex';
    wrapper.style.alignItems = 'center';

    // kds-header: inject into its last inner action group, before any theme/logout.
    if (container.classList.contains('kds-header')) {
      const actions = container.querySelector('div:last-child', '.user-menu, .header-actions');
      if (actions) {
        renderLangSwitcher(wrapper);
        actions.prepend(wrapper);
        return;
      }
    }

    renderLangSwitcher(wrapper);

    // Prefer a right-aligned action area if present.
    const rightZone = container.querySelector('.header-actions, .nav-right, .user-menu, .user-profile-menu, .nav-auth');
    if (rightZone && rightZone !== container) {
      rightZone.prepend(wrapper);
      return;
    }
    // For nav-container / navbar: insert before user menu or at the end.
    const userMenu = container.querySelector('.user-profile-menu, .nav-auth, .user-nav-links');
    if (userMenu && userMenu.parentElement && userMenu.parentElement !== container) {
      userMenu.parentElement.insertBefore(wrapper, userMenu);
      return;
    }
    if (container.classList.contains('header-actions') || container.classList.contains('nav-right')) {
      container.appendChild(wrapper);
      return;
    }
    container.appendChild(wrapper);
    return;
  }

  // Guaranteed fallback: every page must expose a language switcher. If nothing
  // above could host one, inject a fixed floating selector regardless of the
  // presence of any (unrecognised) header, so no page ends up without a
  // translator.
  if (!document.querySelector('.scos-lang-select, #langToggleSelect')) {
    const floating = document.createElement('div');
    floating.setAttribute('data-i18n-floating', '1');
    floating.style.position = 'fixed';
    floating.style.top = '16px';
    floating.style.right = '16px';
    floating.style.zIndex = '9999';
    renderLangSwitcher(floating);
    document.body.appendChild(floating);
  }
}

// Remove any floating (top-right, body-level) fallback language switcher that
// was injected before a proper navbar/header selector became available.
function removeStaleFloatingSwitcher() {
  document.querySelectorAll('[data-i18n-floating]').forEach(function (el) {
    el.remove();
  });
}

// Global window attachments for backward compatibility
window.setLanguage = setLanguage;
window.applyTranslations = applyTranslations;
window.getCurrentLanguage = getCurrentLanguage;
window.renderLangSwitcher = renderLangSwitcher;
window.getText = getText;
window.t = getText;
window.translateStatus = translateStatus;
window.tr = tr;
window.translateErrorMessage = translateErrorMessage;
window.tStatus = translateStatus;

// Initialize
function initI18n() {
  // Load centralized JSON first, then apply (with fallback to embedded)
  loadCentralizedTranslations().then(() => {
    applyTranslations();
    ensureSwitcherInjected();
    triggerLanguageRender();
  });
  // Also apply immediately with embedded translations so page not blank while loading
  applyTranslations();
  ensureSwitcherInjected();
  triggerLanguageRender();
  // Listen to any language selector on page
  document.querySelectorAll('.scos-lang-select, #langToggleSelect, #preferred-language').forEach((select) => {
    // Avoid duplicate listeners by cloning? Use flag
    if (select.dataset.i18nBound) return;
    select.dataset.i18nBound = '1';
    select.addEventListener('change', (e) => setLanguage(e.target.value));
  });
  // Watch for dynamic DOM changes (e.g., admin-layout injected navbar)
  const observer = new MutationObserver(() => {
    if (_applyingTranslations) return;
    ensureSwitcherInjected();
    clearTimeout(window.__i18nDebounce);
    window.__i18nDebounce = setTimeout(applyTranslations, 100);
  });
  observer.observe(document.body, { childList: true, subtree: true });

  // Listen storage changes from other tabs
  window.addEventListener('storage', (e) => {
    if (STORAGE_KEYS.includes(e.key)) {
      applyTranslations();
      triggerLanguageRender();
    }
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initI18n);
} else {
  initI18n();
}

// Also re-apply on language events
window.addEventListener('language:changed', () => {
  applyTranslations();
});
window.addEventListener('languageChanged', () => {
  applyTranslations();
});
